package local.pitv;
import android.content.*;import android.graphics.*;import android.media.*;import android.net.*;import android.os.*;import android.view.*;import android.widget.*;
final class GuidePreview extends FrameLayout {
 java.util.function.Consumer<String> information;final VlcVideoView video;final ImageView artwork;final TextView state;final Handler handler=new Handler();String requested="",playing="";boolean paused=false;int serial=0;
 GuidePreview(Context c){super(c);setBackgroundColor(0xff080d16);artwork=new ImageView(c);artwork.setScaleType(ImageView.ScaleType.FIT_CENTER);addView(artwork,new LayoutParams(-1,-1));video=new VlcVideoView(c);video.autoLive=true;video.setVolume(c.getSharedPreferences("television",0).getBoolean("previewMuted",true));addView(video,new LayoutParams(-1,-1,Gravity.CENTER));video.setAlpha(0f);video.setVisibility(VISIBLE);state=TvStyle.text(c,"Live preview",10);state.setPadding(6,3,6,3);state.setBackgroundColor(0xb0080d16);addView(state,new LayoutParams(-1,-2,Gravity.BOTTOM));setContentDescription("Muted live channel preview");}
 void setImageBitmap(Bitmap bitmap){artwork.setImageBitmap(bitmap);}
 void tune(String address){if(address==null||address.isEmpty()||address.equals(requested))return;requested=address;int ticket=++serial;handler.removeCallbacksAndMessages(null);video.stopPlayback();video.setAlpha(0f);video.setVisibility(VISIBLE);playing="";state.setText("Live preview · muted");handler.postDelayed(()->{if(!paused&&ticket==serial)open(address,ticket,false);},500);}
 void open(String address,int ticket,boolean fallback){if(paused||ticket!=serial)return;playing=address;video.setOnPreparedListener(mp->{if(paused||ticket!=serial)return;boolean muted=getContext().getSharedPreferences("television",0).getBoolean("previewMuted",true);video.setVolume(muted);video.setVisibility(VISIBLE);video.setAlpha(1f);video.start();state.setText(muted?"LIVE · muted":"LIVE");if(information!=null)information.accept(video.technical()+"\n"+video.health()+"\n"+StreamInfo.connection(getContext(),address));});video.setOnErrorListener((mp,w,e)->{if(ticket!=serial)return true;if(!fallback&&address.endsWith(".m3u8")){open(address.substring(0,address.length()-5)+".ts",ticket,true);return true;}video.setAlpha(0f);video.setVisibility(VISIBLE);state.setText("Preview unavailable · OK to watch");return true;});video.setVideoURI(Uri.parse(address));}
 void suspend(){paused=true;serial++;handler.removeCallbacksAndMessages(null);video.stopPlayback();video.setAlpha(0f);video.setVisibility(VISIBLE);}
 void resume(){if(!paused)return;paused=false;String address=requested;requested="";tune(address);}
 @Override protected void onDetachedFromWindow(){suspend();super.onDetachedFromWindow();}
}
